// AppKit + wagmi setup. Reads config from a <script id="wc-config"> JSON tag
// injected by the Pretix checkout template.
import { createAppKit } from '@reown/appkit/react'
import { WagmiAdapter } from '@reown/appkit-adapter-wagmi'
import { mainnet, optimism, polygon, base, arbitrum } from '@reown/appkit/networks'
import type { AppKitNetwork } from '@reown/appkit/networks'

export interface WCConfig {
  wcProjectId: string
  orderCode: string
  orderSecret: string
  /** Pretix order total in USD as a decimal string ("12.34"). Used by the
   *  asset/network picker to compute insufficient-balance gating against the
   *  wallet balances returned from /plugin/wc/wallet-balances/. May be empty
   *  if the template rendered the page without the field (older deploys). */
  orderTotalUsd?: string
  /** Buyer's email from the Pretix Order. Pre-filled into the support-email
   *  body so the buyer doesn't have to retype it. Empty when the order has
   *  no email recorded (rare). */
  buyerEmail?: string
  urlPrefix: string
  /** Pretix organizer slug. Injected server-side because the bundle can't
   *  derive it from `window.location.pathname` when the event runs on a
   *  custom domain (e.g. tickets.devcon.org/, no /{org}/{event}/ prefix). */
  organizer: string
  /** Pretix event slug. Same rationale as `organizer`. */
  event: string
  /** Pretix-native order detail URL, computed server-side via
   *  `build_absolute_uri` so it respects custom-domain configuration. Used
   *  as the post-payment redirect fallback when `frontendOrderUrlTemplate`
   *  is not configured. */
  pretixOrderUrl: string
  /** Pretix's "change payment method" page for this order (absolute, custom
   *  domain aware). Target of the empty-wallet exit in CheckoutStep. Empty
   *  or missing on older templates — the bundle then derives it from
   *  `pretixOrderUrl`. */
  changePaymentUrl?: string
  /** True when a card provider (Stripe) is enabled and allowed for this
   *  order, so the empty-wallet exit can say "pay by card" outright. */
  cardPaymentAvailable?: boolean
  /** True when ANY other payment provider is available for this order.
   *  When false the empty-wallet exit shows no switch shortcut at all. */
  otherPaymentMethodsAvailable?: boolean
  csrfToken: string
  /** Optional support email set in the plugin admin. Shown in a fallback
   *  contact block if the buyer's payment gets stuck; empty string hides it. */
  supportEmail?: string
  /** Optional FE-domain URL template (same setting that overrides the email
   *  `{url}` placeholder). When set, SuccessStep redirects to the FE order
   *  page instead of Pretix's native one — keeps the post-payment landing
   *  consistent with the confirmation email. Supports `{code}` and
   *  `{secret}` substitution. Empty string = fall back to Pretix's order. */
  frontendOrderUrlTemplate?: string
  /** True when this event has only ETH-on-mainnet enabled (the wave-launch
   *  flow). Drives the ConnectStep heading copy. */
  ethMainnetOnly?: boolean
  /** Opt-in: surface Safe / Safe-Apps as a wallet option, with safeTxHash
   *  polling on the send path and safeMessageHash polling on the challenge
   *  sign for multi-sig Safes. Default OFF — multi-sig Safe co-sign can
   *  take hours, and an event that hasn't operationally validated this
   *  path shouldn't expose a "stuck-order" footgun. */
  safePaymentsEnabled?: boolean
  /** Plugin version (`pretix_eth/__init__.py:__version__`). Surfaced via
   *  WCConfig so debug logs and the in-page footer don't need a separate
   *  injection path. */
  pluginVersion?: string
}

export function readConfig(): WCConfig {
  const el = document.getElementById('wc-config')
  if (!el) throw new Error('wc-config script tag missing from template')
  return JSON.parse(el.textContent || '{}') as WCConfig
}

const NETWORKS: [AppKitNetwork, ...AppKitNetwork[]] = [
  mainnet, optimism, polygon, base, arbitrum,
]

// Wallets pinned to the top of the AppKit picker. Mirrors devcon's
// src/context/appkit-config.ts so the same shortlist appears across surfaces.
// IDs come from cloud.reown.com's wallet directory.
const FEATURED_WALLET_IDS = [
  'ecc4036f814562b41a5268adc86270fba1365471402006302e70169465b7ac18', // Zerion
  '1ae92b26df02f0abca6304df07debccd18262fdf5fe82daa81593582dac9a369', // Rainbow
  'fd20dc426fb37566d803205b19bbc1d4096b248ac04548e3cfb6b3a38bd033aa', // Coinbase
  'c57ca95b47569778a828d19178114f4db188b89b763c899ba0be274e97267d96', // MetaMask
]

// Wallet IDs we always hide. Safe is excluded by default — the bundle
// only bridges through Safe Tx Service / Safe Messages API for safeTxHash
// + safeMessageHash recovery when the `safe_payments_enabled` admin flag
// is on. When the flag is off (default) we leave Safe in this list so a
// buyer with a Safe gets clearly told the option isn't supported (no row
// at all, vs. a row that completes payment onchain but never recovers).
const SAFE_WC_WALLET_ID = '225affb176778569276e484e1b92637ad061b01e13a048b35a9d280c3b58970f'
const ALWAYS_EXCLUDED_WALLET_IDS: string[] = []

export function initAppKit(projectId: string, opts?: { safePaymentsEnabled?: boolean }) {
  const wagmiAdapter = new WagmiAdapter({
    projectId,
    networks: NETWORKS,
  })

  const excludeWalletIds = [
    ...ALWAYS_EXCLUDED_WALLET_IDS,
    ...(opts?.safePaymentsEnabled ? [] : [SAFE_WC_WALLET_ID]),
  ]

  const appKit = createAppKit({
    adapters: [wagmiAdapter],
    networks: NETWORKS,
    projectId,
    // What the wallet shows as the requesting dApp on connect and on every
    // signing screen. With no name or icon, wallets render a blank tile next
    // to the domain, which reads as an anonymous site in front of a payment.
    // The icon is an absolute PNG (wallets don't reliably follow redirects
    // or render .ico).
    metadata: {
      name: 'Devcon Pretix crypto payment',
      description: 'Pay for your Devcon ticket with crypto',
      url: typeof window !== 'undefined' ? window.location.origin : '',
      icons: ['https://devcon.org/android-chrome-192x192.png'],
    },
    features: {
      analytics: false,
      email: false,
      socials: [],
    },
    featuredWalletIds: FEATURED_WALLET_IDS,
    excludeWalletIds: excludeWalletIds,
  })

  return { wagmiAdapter, appKit, open: () => appKit.open() }
}

// Module-level singleton — set by index.tsx, used by components
export let appKitInstance: ReturnType<typeof createAppKit> | null = null

export function setAppKitInstance(ak: ReturnType<typeof createAppKit>) {
  appKitInstance = ak
}
